insert into public.avara_destinations(id,name,region,district,category,description,latitude,longitude,coordinate_status,season_note,suggested_days,tags,published,review_status) values ('od_harishankar','Harishankar Waterfall & Temple','Odisha','Balangir','Waterfall','Located on the southern slopes of Gandhamardan hills, Harishankar is a place of supreme natural and spiritual splendor. The perennial mountain stream cascades over granite boulders creating natural bathing slides. The 15th-century temple enshrines both Vishnu (Hari) and Shiva (Shankar) in unified worship.','20.85','82.85','needs_review','October – March','1',array['waterfall','temple','gandhamardan hills','harihara','natural stream','ayurveda']::text[],true,'source_linked') on conflict(id) do update set name=excluded.name,region=excluded.region,district=excluded.district,category=excluded.category,description=excluded.description,latitude=excluded.latitude,longitude=excluded.longitude,season_note=excluded.season_note,tags=excluded.tags,coordinate_status=excluded.coordinate_status,suggested_days=excluded.suggested_days,review_status=excluded.review_status;
