insert into public.avara_destinations(id,name,region,district,category,description,latitude,longitude,coordinate_status,season_note,suggested_days,tags,published,review_status) values ('od_koili_ghoghar','Koili Ghoghar Waterfall & Cave Temple','Odisha','Jharsuguda','Waterfall','Koili Ghoghar is nestled in the dense reserve forests of Lakhanpur in Jharsuguda district. The rivulets of the ''Ahiraj'' nallah cascade down stepped rock tiers from a height of 200 feet into a tranquil natural gorge. Inside a rock cave beneath the stream sits a submerged, perennially wet Shiva Lingam known as Maheshwarnath.','21.6833','83.5667','needs_review','October – March','1',array['waterfall','cave temple','submerged lingam','sal forest','stream','nature']::text[],true,'source_linked') on conflict(id) do update set name=excluded.name,region=excluded.region,district=excluded.district,category=excluded.category,description=excluded.description,latitude=excluded.latitude,longitude=excluded.longitude,season_note=excluded.season_note,tags=excluded.tags,coordinate_status=excluded.coordinate_status,suggested_days=excluded.suggested_days,review_status=excluded.review_status;
