insert into public.avara_destinations(id,name,region,district,category,description,latitude,longitude,coordinate_status,season_note,suggested_days,tags,published,review_status) values ('od_patora_dam','Patora Dam & Yogiswar Temple','Odisha','Nuapada','Lake','Built across the Jonk river, Patora Dam (officially Upper Jonk Irrigation Project) is set amid dramatic cliff formations and serene waters. Adjacent to the reservoir, the modern Yogiswar temple features a grand Shiva statue and manicured hillside gardens.','20.7333','82.55','needs_review','October – March','1',array['dam','reservoir','lake','shiva','hills','picnic','boating']::text[],true,'needs_review') on conflict(id) do update set name=excluded.name,region=excluded.region,district=excluded.district,category=excluded.category,description=excluded.description,latitude=excluded.latitude,longitude=excluded.longitude,season_note=excluded.season_note,tags=excluded.tags,coordinate_status=excluded.coordinate_status,suggested_days=excluded.suggested_days,review_status=excluded.review_status;
insert into public.avara_destinations(id,name,region,district,category,description,latitude,longitude,coordinate_status,season_note,suggested_days,tags,published,review_status) values ('od_sunabeda_sanctuary','Sunabeda Wildlife Sanctuary & Canyon','Odisha','Nuapada','Wildlife','Sunabeda Wildlife Sanctuary is an extraordinary ecological wonderland covering 600 sq km across a high plateau carved with dramatic canyons, gorges, and 11 waterfalls including Beniadhara and Kharaldhara. Formed in dry deciduous forest, it serves as an important catchment for the Jonk river.','20.6','82.4667','needs_review','November – April','2',array['tiger reserve','canyon','waterfalls','plateau','barasingha','wilderness']::text[],true,'source_linked') on conflict(id) do update set name=excluded.name,region=excluded.region,district=excluded.district,category=excluded.category,description=excluded.description,latitude=excluded.latitude,longitude=excluded.longitude,season_note=excluded.season_note,tags=excluded.tags,coordinate_status=excluded.coordinate_status,suggested_days=excluded.suggested_days,review_status=excluded.review_status;
