insert into public.avara_destinations(id,name,region,district,category,description,latitude,longitude,coordinate_status,season_note,suggested_days,tags,published,review_status) values ('od_boudh_star_temples','Star-Shaped Temples of Boudh','Odisha','Boudh','Heritage','The three temples of Rameswar, Jogiswar, and Paschimeswar in Boudh town are an architectural wonder of medieval India. Constructed in the 9th century AD under the Bhanja rulers, each temple''s sanctum sits upon an eight-pointed star platform with intricately sculpted Shaivite devatas in red sandstone.','20.84','84.32','needs_review','October – March','1',array['star-shaped','9th century','bhanja dynasty','unique architecture','shiva','heritage']::text[],true,'needs_review') on conflict(id) do update set name=excluded.name,region=excluded.region,district=excluded.district,category=excluded.category,description=excluded.description,latitude=excluded.latitude,longitude=excluded.longitude,season_note=excluded.season_note,tags=excluded.tags,coordinate_status=excluded.coordinate_status,suggested_days=excluded.suggested_days,review_status=excluded.review_status;
insert into public.avara_destinations(id,name,region,district,category,description,latitude,longitude,coordinate_status,season_note,suggested_days,tags,published,review_status) values ('od_boudh_buddha','Giant Seated Buddha of Boudh','Odisha','Boudh','Heritage','Boudh was historically a major center of Vajrayana and Tantric Buddhism in ancient Odra desa. In the heart of the town sits a colossal 7-foot high black stone statue of Lord Buddha seated in Bhumisparsha mudra on a lotus throne, flanked by Gandharvas and celestial apsaras.','20.835','84.325','needs_review','October – March','1',array['buddhism','9th century','bhumisparsha','monolith','heritage','peaceful']::text[],true,'needs_review') on conflict(id) do update set name=excluded.name,region=excluded.region,district=excluded.district,category=excluded.category,description=excluded.description,latitude=excluded.latitude,longitude=excluded.longitude,season_note=excluded.season_note,tags=excluded.tags,coordinate_status=excluded.coordinate_status,suggested_days=excluded.suggested_days,review_status=excluded.review_status;
insert into public.avara_destinations(id,name,region,district,category,description,latitude,longitude,coordinate_status,season_note,suggested_days,tags,published,review_status) values ('od_pradhanpat','Pradhanpat Waterfall & Basanta Nivas','Odisha','Deogarh','Waterfall','Pradhanpat is a mesmerizing waterfall situated less than 1 km from the historic royal town of Deogarh. Cascading from the Pradhanpat hill into crystalline pools, the waterfall is bordered by the heritage Basanta Nivas and Lalit Basanta royal summer palaces built by King Sir Basudeb Sudhal Deb in the late 19th century.','21.5333','84.7333','needs_review','October – March','1',array['waterfall','palace','hydro power history','nature','scenic','heritage']::text[],true,'needs_review') on conflict(id) do update set name=excluded.name,region=excluded.region,district=excluded.district,category=excluded.category,description=excluded.description,latitude=excluded.latitude,longitude=excluded.longitude,season_note=excluded.season_note,tags=excluded.tags,coordinate_status=excluded.coordinate_status,suggested_days=excluded.suggested_days,review_status=excluded.review_status;
insert into public.avara_destinations(id,name,region,district,category,description,latitude,longitude,coordinate_status,season_note,suggested_days,tags,published,review_status) values ('od_kurudkut','Kurudkut Hydro Falls & Forest Valley','Odisha','Deogarh','Nature','Kurudkut is an enchanting jungle cascade located 15 km from Deogarh town. Famous as the original mountain source used by Raja Sir Basudeb Sudhal Deb to pioneer hydro-electricity in the former princely state of Bamra in the 1890s, it offers serene nature trails and lush forest picnics.','21.5833','84.8167','needs_review','October – March','1',array['waterfall','forest','valley','trekking','solitude','green']::text[],true,'needs_review') on conflict(id) do update set name=excluded.name,region=excluded.region,district=excluded.district,category=excluded.category,description=excluded.description,latitude=excluded.latitude,longitude=excluded.longitude,season_note=excluded.season_note,tags=excluded.tags,coordinate_status=excluded.coordinate_status,suggested_days=excluded.suggested_days,review_status=excluded.review_status;
insert into public.avara_destinations(id,name,region,district,category,description,latitude,longitude,coordinate_status,season_note,suggested_days,tags,published,review_status) values ('od_devkund','Devkund Sacred Waterfalls & Kundas','Odisha','Mayurbhanj','Waterfall','Devkund (''Bathtub of the Gods'') is situated in the outer buffer zone of Simlipal Biosphere Reserve. Flowing from the hills of Udala, the mountain river creates five successive natural pools (Kundas), the deepest being Devkund, overlooked by the revered temple of Goddess Ambika on a high rock cliff.','21.6833','86.4833','needs_review','November – March','1',array['waterfall','5 natural pools','simlipal buffer','goddess ambika','forest trek','nature']::text[],true,'source_linked') on conflict(id) do update set name=excluded.name,region=excluded.region,district=excluded.district,category=excluded.category,description=excluded.description,latitude=excluded.latitude,longitude=excluded.longitude,season_note=excluded.season_note,tags=excluded.tags,coordinate_status=excluded.coordinate_status,suggested_days=excluded.suggested_days,review_status=excluded.review_status;
