insert into public.avara_destinations(id,name,region,district,category,description,latitude,longitude,coordinate_status,season_note,suggested_days,tags,published,review_status) values ('od_ghanteswari','Maa Ghanteswari Temple (The Bell Temple)','Odisha','Sambalpur','Heritage','Maa Ghanteswari Temple is situated on the banks of river Mahanadi at Chiplima. Known as the ''Bell Temple of Odisha'', the entire shrine compound is blanketed with thousands of chiming brass and copper bells of all sizes, tied by devotees whose wishes have been fulfilled. Historically, the bells alerted ancient sailors to river whirlpools.','21.35','83.9167','needs_review','October – March','1',array['bell temple','militude of bells','mahanadi river','chiplima','spiritual','unique']::text[],true,'source_linked') on conflict(id) do update set name=excluded.name,region=excluded.region,district=excluded.district,category=excluded.category,description=excluded.description,latitude=excluded.latitude,longitude=excluded.longitude,season_note=excluded.season_note,tags=excluded.tags,coordinate_status=excluded.coordinate_status,suggested_days=excluded.suggested_days,review_status=excluded.review_status;
