insert into public.avara_destinations(id,name,region,district,category,description,latitude,longitude,coordinate_status,season_note,suggested_days,tags,published,review_status) values ('od_ratnagiri_buddhist','Ratnagiri Buddhist University & Monasteries','Odisha','Jajpur','Heritage','Ratnagiri (''Hill of Jewels'') was one of ancient Asia''s foremost universities of Mahayana and Vajrayana Buddhism. Excavated by the ASI, the complex revealed a massive central stupa surrounded by hundreds of votive stupas, an imposing two-story monastery with an exquisitely carved chlorite portal, and colossal Buddha heads.','20.6417','86.3333','needs_review','October – March','1',array['buddhism','diamond triangle','unesco tentative','vajrayana','monastery','chlorite gate']::text[],true,'source_linked') on conflict(id) do update set name=excluded.name,region=excluded.region,district=excluded.district,category=excluded.category,description=excluded.description,latitude=excluded.latitude,longitude=excluded.longitude,season_note=excluded.season_note,tags=excluded.tags,coordinate_status=excluded.coordinate_status,suggested_days=excluded.suggested_days,review_status=excluded.review_status;
