insert into public.avara_destinations(id,name,region,district,category,description,latitude,longitude,coordinate_status,season_note,suggested_days,tags,published,review_status) values ('od_hukitola_palace','Hukitola French-British Island Palace','Odisha','Kendrapara','Heritage','Constructed in 1867 following the Great Orissa Famine, Hukitola is a magnificent colonial stone palace on an island off False Point. Featuring an ingenious sloped roof that funneled rainwater into massive underground filtering cisterns, it provided complete freshwater self-sufficiency amidst the sea.','20.4','86.8','needs_review','November – March','1',array['island palace','rainwater harvesting','1867','coastal','heritage','boat journey']::text[],true,'needs_review') on conflict(id) do update set name=excluded.name,region=excluded.region,district=excluded.district,category=excluded.category,description=excluded.description,latitude=excluded.latitude,longitude=excluded.longitude,season_note=excluded.season_note,tags=excluded.tags,coordinate_status=excluded.coordinate_status,suggested_days=excluded.suggested_days,review_status=excluded.review_status;
insert into public.avara_destinations(id,name,region,district,category,description,latitude,longitude,coordinate_status,season_note,suggested_days,tags,published,review_status) values ('od_talasari_beach','Talasari Beach & Subarnarekha Estuary','Odisha','Balasore','Beach','Talasari in northern Balasore district is celebrated for its peaceful beaches, tranquil river backwaters, and palm-fringed sand dunes. At low tide, visitors walk across shallow backwaters to reach the main beach, which comes alive with thousands of dancing red ghost crabs.','21.5833','87.45','needs_review','October – March','1',array['beach','red crabs','subarnarekha river','casuarina','backwaters','peaceful']::text[],true,'source_linked') on conflict(id) do update set name=excluded.name,region=excluded.region,district=excluded.district,category=excluded.category,description=excluded.description,latitude=excluded.latitude,longitude=excluded.longitude,season_note=excluded.season_note,tags=excluded.tags,coordinate_status=excluded.coordinate_status,suggested_days=excluded.suggested_days,review_status=excluded.review_status;
